use vstd::prelude::*;

verus! {

fn max_of_list(lst: Vec<i32>) -> (result: i32)
    requires
        lst.len() > 0,
    ensures
        exists|i: int|
            0 <= i && i < lst.len() && result == lst[i],
        forall|j: int|
            0 <= j && j < lst.len() ==> lst[j] <= result,
{
    let n = lst.len();
    let mut idx: usize = 1;

    let mut max_val: i32 = lst[0];
    let mut max_idx: usize = 0;

    while idx < n
        invariant
            n == lst.len(),
            1 <= n,
            1 <= idx <= n,
            max_idx < n,
            // max_val is some element seen so far
            max_val == lst[max_idx as int],
            max_idx < idx,
            // max_val is an upper bound for all elements seen so far
            forall|j: int| 0 <= j && j < idx ==> lst[j] <= max_val,
        decreases n - idx
    {
        if lst[idx] > max_val {
            max_val = lst[idx];
            max_idx = idx;
        }
        idx = idx + 1;
    }

    // Postconditions follow from the loop invariants at idx == n.
    max_val
}

}

